let sustainabilityFocus='All resources',processStage=-1,kpiCategory='All pillars';
const palette=['#a0f7da','#a9ccff','#d4b4fa','#ffd09d','#f5a5ce'];
function scopeData(){const f=state.factory<0?1:factories[state.factory].output/428640,p=$('#period').value||'Today',days=p==='Today'?1:p==='This week'?7:30;return {f,p,days,total:f*days,labels:p==='Today'?['06:00','08:00','10:00','12:00','14:00','16:00']:p==='This week'?['Mon','Tue','Wed','Thu','Fri','Sat']:['W1','W2','W3','W4','W5','W6']}}
function nfmt(v){return Number(v).toLocaleString(undefined,{maximumFractionDigits:2})}
function chartPoint(title,label,value,unit){openModal(title,`<div class="metric-reading">${nfmt(value)} <small>${unit}</small></div><strong>${label}</strong><br><br>Scope: ${state.factory<0?'All factories':factories[state.factory].name}<br>Period: ${$('#period').value||'Today'}<br><br>Illustrative business data. Use this view to compare performance, targets and areas requiring action.`)}
function pointAttrs(title,label,value,unit){return `tabindex="0" role="button" aria-label="${label}: ${nfmt(value)} ${unit}" onclick="chartPoint('${title}','${label}',${value},'${unit}')" onkeydown="if(event.key==='Enter')chartPoint('${title}','${label}',${value},'${unit}')"`}
function analyticsChart(title,subtitle,labels,values,unit,options={}){const max=Math.max(...values,...(options.target?[options.target]:[]))*1.2||1,x=i=>52+i*(460/Math.max(labels.length-1,1)),y=v=>174-v/max*137;const marks=options.type==='bar'?values.map((v,i)=>`<rect ${pointAttrs(title,labels[i],v,unit)} x="${x(i)-14}" y="${y(v)}" width="28" height="${174-y(v)}" rx="4" fill="${palette[i%palette.length]}"><title>${labels[i]}: ${nfmt(v)} ${unit}</title></rect>`).join(''):`<path d="M${values.map((v,i)=>x(i)+','+y(v)).join(' L')}" fill="none" stroke="${palette[0]}" stroke-width="3"/>${values.map((v,i)=>`<circle ${pointAttrs(title,labels[i],v,unit)} cx="${x(i)}" cy="${y(v)}" r="5" fill="${palette[0]}" stroke="#10223a" stroke-width="2"><title>${labels[i]}: ${nfmt(v)} ${unit}</title></circle>`).join('')}`;return `<section class="panel analytics-panel"><div class="panelhead"><div><h2>${title}</h2><small>${subtitle}</small></div><span class="chart-unit">${unit}</span></div><svg class="analytics-svg" viewBox="0 0 560 214" aria-label="${title} in ${unit}">${[0,.5,1].map(r=>`<line x1="44" x2="534" y1="${y(max*r)}" y2="${y(max*r)}" stroke="#91abc01c"/><text x="36" y="${y(max*r)+4}" text-anchor="end">${nfmt(max*r)}</text>`).join('')}${options.target?`<line x1="44" x2="534" y1="${y(options.target)}" y2="${y(options.target)}" stroke="#ffc776" stroke-dasharray="5 5"/><text x="534" y="${y(options.target)-6}" text-anchor="end" fill="#ffc776">Target ${options.target}</text>`:''}${marks}${labels.map((l,i)=>`<text x="${x(i)}" y="199" text-anchor="middle">${l}</text>`).join('')}</svg><div class="chart-caption"><span>${options.target?'Actual with target reference':'Select a point for details'}</span><span>Demo data</span></div></section>`}
function compositionChart(title,subtitle,labels,values,unit){const sum=values.reduce((a,b)=>a+b,0);let offset=0;const arcs=values.map((v,i)=>{const arc=`<circle ${pointAttrs(title,labels[i],v,unit)} cx="95" cy="95" r="66" fill="none" stroke="${palette[i]}" stroke-width="21" stroke-dasharray="${v/sum*414.69} ${414.69-v/sum*414.69}" stroke-dashoffset="${-offset}" transform="rotate(-90 95 95)"><title>${labels[i]}: ${nfmt(v)} ${unit}</title></circle>`;offset+=v/sum*414.69;return arc}).join('');return `<section class="panel analytics-panel"><div class="panelhead"><div><h2>${title}</h2><small>${subtitle}</small></div><span class="chart-unit">${unit}</span></div><div class="composition"><svg viewBox="0 0 190 190" class="composition-svg" aria-label="${title}">${arcs}<text x="95" y="91" text-anchor="middle" class="composition-total">${nfmt(sum)}</text><text x="95" y="113" text-anchor="middle">${unit} total</text></svg><div class="composition-legend">${labels.map((l,i)=>`<button onclick="chartPoint('${title}','${l}',${values[i]},'${unit}')"><span class="legend-dot" style="background:${palette[i]}"></span><span>${l}</span><strong>${Math.round(values[i]/sum*100)}%</strong></button>`).join('')}</div></div></section>`}
function sustainabilityCharts(){const s=scopeData(),mul=arr=>arr.map(v=>+(v*s.total).toFixed(2)),focus=sustainabilityFocus;const sections=[['Energy',analyticsChart('Energy consumption','Operating-period profile',s.labels,mul([22,29,35,32,26,24]),'MWh')],['Energy',analyticsChart('Energy cost per unit','Efficiency against budget',s.labels,[.96,.93,.89,.87,.86,.84],'EGP/unit',{target:.9})],['Water',analyticsChart('Water withdrawal','Demand across production areas',['Process','CIP','Cooling','Facility'],mul([1080,680,540,340]),'m³',{type:'bar'})],['Water',analyticsChart('Water reuse','Share of water demand recovered',s.labels,[58,60,63,65,67,68],'%',{target:65})],['Emissions',analyticsChart('Carbon emissions','Operating-period emissions profile',s.labels,mul([26,23,22,20,18,15]),'tCO₂e')],['Emissions',compositionChart('Emissions by source','Prioritize the largest carbon contributors',['Electricity','Fuel','Purchased steam'],mul([74,31,19]),'tCO₂e')],['Waste',compositionChart('Waste destination','Recovery and disposal pathways',['Recycled','Recovered','Disposed'],mul([11.7,4.86,1.44]),'tonnes')],['Waste',analyticsChart('Waste recovery','Progress against diversion target',s.labels,[84,86,88,89,91,92],'%',{target:90})]];return `<div class="business-strip"><strong>Sustainability outlook</strong><span>Water reuse and waste recovery exceed target. Lower energy cost per unit is improving the cost of production.</span></div><div class="analytics-toolbar"><div><h2>Environmental performance</h2><small>${s.p} · ${state.factory<0?'All factories':factories[state.factory].name}</small></div><div class="segmented">${['All resources','Energy','Water','Emissions','Waste'].map(t=>`<button class="${focus===t?'active':''}" onclick="sustainabilityFocus='${t}';render()">${t}</button>`).join('')}</div></div><div class="analytics-grid">${sections.filter(x=>focus==='All resources'||focus===x[0]).map(x=>x[1]).join('')}</div><div class="insight">Targets: energy cost ≤ EGP 0.90/unit; water reuse ≥ 65%; waste recovery ≥ 90%. All charts and targets are illustrative.</div>`}
function processView(){const s=scopeData(),batchCount=state.factory<0?24:8,counts=state.factory<0?[3,7,6,4,4]:[1,2,2,1,2],stages=['Preparation','Processing','In-process quality','Transfer','Ready for packaging'];return `<div class="business-strip"><strong>Process flow</strong><span>Understand where batches are, what is holding them, and the impact on downstream packaging.</span></div><section class="panel"><div class="panelhead"><div><h2>Batch journey · ${batchCount} active batches</h2><small>Line ${state.line+1} selected · Select a stage to inspect its queue</small></div><button onclick="processStage=-1;render()">All stages</button></div><div class="stage-grid">${stages.map((t,i)=>`<button class="stage ${processStage===i?'active':''}" onclick="processStage=${i};render()"><span class="stage-number">0${i+1}</span><strong>${t}</strong><b>${counts[i]} <small>batches</small></b><span class="${i===2?'warning':'positive'}">${i===2?'1 review required':i===4?'Available to packaging':'On schedule'}</span></button>`).join('')}</div></section><div class="analytics-grid" style="margin-top:18px"><section class="panel"><div class="panelhead"><div><h2>${processStage<0?'Priority batches':stages[processStage]+' queue'}</h2><small>Operational progress and business impact</small></div><span class="pill">Line ${state.line+1}</span></div><div class="table-scroll"><table><tr><th>Batch / product</th><th>Stage</th><th>Schedule</th><th>Impact</th><th></th></tr>${[0,1,2].map((n)=>{let stage=processStage<0?[1,2,4][n]:processStage;return `<tr><td><strong>BT-${26041+state.line*10+n}</strong><br><small>${['Tablets','Capsules','Sterile vials'][state.line]}</small></td><td>${stages[stage]}</td><td class="${stage===2?'warning':'positive'}">${stage===2?'Review pending':'On schedule'}</td><td>${stage===2?'Packaging release at risk':stage===4?'Ready for next step':'No delivery impact'}</td><td><button onclick="batchBusinessDetail(${n},${stage})">Review</button></td></tr>`}).join('')}</table></div></section><section class="panel"><h2>Flow constraints & handover</h2><div class="insight"><strong class="warning">Quality review · 1 batch</strong><br>Awaiting in-process review before transfer. Potential impact: packaging start delayed by 45 minutes.</div><div class="insight"><strong class="positive">Packaging readiness</strong><br>${counts[4]} batches are ready for packaging. Prioritize those linked to the earliest customer commitments.</div><div class="row" style="margin-top:22px"><button onclick="go('Quality')">Quality review →</button><button onclick="go('Packaging')">Packaging →</button></div></section>${analyticsChart('Batch cycle time','Elapsed time from preparation to packaging readiness',s.labels,[7.8,7.5,7.9,7.2,7.1,6.9],'hours',{target:7.5})}${analyticsChart('Batch status','Current work in progress', ['On time','At risk','On hold'],[batchCount-2,1,1],'batches',{type:'bar'})}</div>`}
function batchBusinessDetail(n,stage){const stages=['Preparation','Processing','In-process quality','Transfer','Ready for packaging'];openModal('Batch BT-'+(26041+state.line*10+n),`<strong>${['Tablets','Capsules','Sterile vials'][state.line]} · Line ${state.line+1}</strong><br>Current stage: ${stages[stage]}<br>Schedule: ${stage===2?'Review pending':'On schedule'}<br><br>Business impact: ${stage===2?'Packaging start may be delayed by 45 minutes. Prioritize review to protect the production plan.':'No delivery impact currently expected.'}<br><br><button class="action" onclick="$('#modal').close();go('Production Overview')">View overall production performance →</button>`)}
function productionSummary(){const s=scopeData(),actual=[160000,132640,136000].map(v=>Math.round(v*s.total)),plan=[170000,140000,142000].map(v=>Math.round(v*s.total));return `<div class="business-strip"><strong>Production performance</strong><span>Compare output with the operating plan, identify lost capacity, and protect delivery commitments.</span></div><div class="analytics-grid"><section class="panel"><div class="panelhead"><div><h2>Output against plan</h2><small>Finished units · ${s.p}</small></div><span class="pill">94.8% attainment</span></div><div class="plan-list">${actual.map((a,i)=>`<button onclick="reviewProductionLine(${i})"><div class="row"><strong>Line ${i+1}</strong><span>${nfmt(a)} / ${nfmt(plan[i])} units</span></div><div class="target-track"><i style="width:${a/plan[i]*100}%;background:${palette[i]}"></i><span class="target-end"></span></div><div class="row"><small>${(a/plan[i]*100).toFixed(1)}% of plan</small><small>Review process →</small></div></button>`).join('')}</div></section>${analyticsChart('Production trend','Actual finished output',s.labels,[48,61,70,84,89,76.64].map(v=>+(v*s.total).toFixed(2)),'k units')}${analyticsChart('Equipment effectiveness by line','Availability × performance × quality',['Line 1','Line 2','Line 3'],[89.2,84.8,88.1],'%',{type:'bar',target:85})}${analyticsChart('Lost production time','Where capacity was lost',['Changeover','Minor stops','Material','Quality'],[1.8,1.1,.6,.4].map(v=>+(v*s.days).toFixed(1)),'hours',{type:'bar'})}</div><section class="panel" style="margin-top:18px"><div class="panelhead"><h2>Production commitments</h2><small>Performance and customer impact</small></div><div class="table-scroll"><table><tr><th>Line</th><th>Plan attainment</th><th>Quality yield</th><th>Delivery impact</th><th></th></tr>${actual.map((a,i)=>`<tr><td>Line ${i+1}</td><td>${(a/plan[i]*100).toFixed(1)}%</td><td>${[98.6,97.8,98.2][i]}%</td><td class="${i===1?'warning':'positive'}">${i===1?'2 orders need recovery review':'On track'}</td><td><button onclick="reviewProductionLine(${i})">Explore process →</button></td></tr>`).join('')}</table></div></section>`}
function reviewProductionLine(i){state.line=i;processStage=-1;go('Process')}
const importantKpis=[
{name:'Overall quality',group:'Quality',value:'98.2%',target:'≥ 98%',status:'On target',desc:'First-pass accepted units as a share of all units produced.',chart:'quality'},
{name:'Customer satisfaction',group:'Customer',value:'92%',target:'≥ 90%',status:'On target',desc:'Overall customer satisfaction score.',chart:'satisfaction'},
{name:'Top 7 product ratings',group:'Customer',value:'4.7 / 5',target:'≥ 4.5 / 5',status:'On target',desc:'Average product ratings across seven product families.',chart:'ratings'},
{name:'Regulatory compliance',group:'Compliance',value:'96%',target:'100%',status:'Needs review',desc:'Share of applicable compliance checks completed successfully.',chart:'compliance'},
{name:'Recall rate',group:'Compliance',value:'0.1%',target:'≤ 0.2%',status:'On target',desc:'Recalled units as a share of distributed units.',chart:'recall'},
{name:'Legal issues',group:'Compliance',value:'2 open',target:'0 open',status:'Needs review',desc:'Open legal or regulatory cases requiring management attention.',chart:'legal'},
{name:'Delivery status',group:'Delivery',value:'95.4%',target:'≥ 93%',status:'On target',desc:'Orders delivered by their committed date.',chart:'delivery'},
{name:'Top 5 warranty claim products',group:'Customer',value:'14 claims',target:'≤ 15 claims',status:'On target',desc:'Warranty claims concentrated in the five most affected product families.',chart:'warranty'},
{name:'Consumer complaints',group:'Customer',value:'29 cases',target:'≤ 25 cases',status:'Needs review',desc:'Customer complaints grouped by their primary cause.',chart:'complaints'},
{name:'Supplier defect rate',group:'Quality',value:'1.9%',target:'≤ 2%',status:'On target',desc:'Rejected incoming units as a share of inspected supplier units.',chart:'supplier'},
{name:'Defect rate',group:'Quality',value:'1.8%',target:'≤ 2%',status:'On target',desc:'Production units failing their initial quality check.',chart:'defects'},
{name:'Cost of poor quality',group:'Quality',value:'EGP 32k',target:'≤ EGP 35k',status:'On target',desc:'Combined cost of scrap, rework, returns and extra inspection.',chart:'cost'},
{name:'Top 5 downtime causes',group:'Operations',value:'3.9 h',target:'≤ 4 h',status:'On target',desc:'Production time lost across the five largest downtime causes.',chart:'downtime'}
];
function kpiDetail(i){const k=importantKpis[i];openModal(k.name,`<div class="metric-reading">${k.value}</div><strong>${k.status} · Target ${k.target}</strong><br><br>${k.desc}<br><br>Scope: ${state.factory<0?'All factories':factories[state.factory].name}<br><small>Demo snapshot. Targets and calculation rules are illustrative.</small>`)}
function kpiChart(k){const title=k.name;switch(k.chart){case 'quality':return analyticsChart(title,'Quality by product type',['Tablets','Capsules','Vials'],[98.6,97.8,98.2],'%',{type:'bar',target:98});case 'satisfaction':return compositionChart(title,'Distribution of survey responses',['Dissatisfied','Neutral','Satisfied','Very satisfied'],[8,14,42,36],'%');case 'ratings':return analyticsChart(title,'Product-family customer ratings',['API','Vaccine','Devices','Formul.','WIP','Utility','Warehouse'],[4.8,4.7,4.9,4.6,4.5,4.8,4.6],'/ 5',{type:'bar',target:4.5});case 'compliance':return analyticsChart(title,'Check completion by compliance area',['GMP','Training','Records','Audit'],[98,96,94,96],'%',{type:'bar',target:100});case 'recall':return analyticsChart(title,'Recall-rate trend',['P1','P2','P3','P4','P5','P6'],[.18,.15,.12,.14,.11,.1],'%',{target:.2});case 'legal':return analyticsChart(title,'Open cases by type',['Contract','Regulatory','Other'],[1,1,0],'cases',{type:'bar'});case 'delivery':return compositionChart(title,'Customer order fulfillment',['On time','Late'],[95.4,4.6],'%');case 'warranty':return analyticsChart(title,'Highest claim counts',['Tablets','Vials','Capsules','Devices','Kits'],[5,3,3,2,1],'claims',{type:'bar'});case 'complaints':return compositionChart(title,'Consumer complaints by cause',['Product','Delivery','Quality','Support'],[12,7,6,4],'cases');case 'supplier':return analyticsChart(title,'Supplier incoming-quality trend',['P1','P2','P3','P4','P5','P6'],[2.5,2.2,2.3,2,1.8,1.9],'%',{target:2});case 'defects':return analyticsChart(title,'Defect rates across lines',['Line 1','Line 2','Line 3'],[1.4,2.2,1.8],'%',{type:'bar',target:2});case 'cost':return analyticsChart(title,'Cost contribution by category',['Scrap','Rework','Returns','Inspection'],[12,10,6,4],'EGP k',{type:'bar'});default:return analyticsChart(title,'Time lost by cause',['Changeover','Stops','Material','QA hold','Other'],[1.8,1.1,.5,.3,.2],'hours',{type:'bar'})}}
function businessKpiView(){const selected=importantKpis.filter(k=>kpiCategory==='All pillars'||k.group===kpiCategory);return `<div class="business-strip"><strong>Leadership scorecard</strong><span>The priority measures from your reference: customer, quality, compliance, delivery and operational performance.</span></div><div class="analytics-toolbar"><div><h2>Business pillars & KPIs</h2><small>13 priority measures · Illustrative snapshot · Select any KPI for its definition</small></div><div class="segmented">${['All pillars','Quality','Customer','Compliance','Delivery','Operations'].map(t=>`<button class="${kpiCategory===t?'active':''}" onclick="kpiCategory='${t}';render()">${t}</button>`).join('')}</div></div><div class="scorecard-grid">${selected.map(k=>`<button class="scorecard" onclick="kpiDetail(${importantKpis.indexOf(k)})"><div class="row"><small>${k.group}</small><span class="${k.status==='On target'?'positive':'warning'}">${k.status}</span></div><h3>${k.name}</h3><strong class="score-value">${k.value}</strong><div class="row"><small>Target ${k.target}</small><span>↗</span></div></button>`).join('')}</div><div class="analytics-grid" style="margin-top:20px">${selected.map(k=>kpiChart(k)).join('')}</div><div class="note">Business KPIs consolidates leadership measures. Quality retains operational quality monitoring, CIP and PAT details. Demo snapshot values remain fixed when changing the time frame; live history is not connected.</div>`}
